import json,os,statistics,subprocess,sys
from pathlib import Path
root=Path.cwd();folder=root/'.cache/native-simd';binary=folder/'micro'
policy=json.loads((folder/'policy.json').read_text())
cases=[('column',n,65521) for n in [16,64,256,1024]]
cases += [('column',256,2147483659)]
cases += [('ntt',n,0) for n in [16,64,256,1024,4096]]
cases += [('dot',n,2305843009213693951) for n in [32,64,128,256,1024]]
cases += [('dot',256,4611686018427387847),('dot',256,1099511627791)]
if sys.argv[1:]==['dot']:cases=[x for x in cases if x[0]=='dot']
report={'policy':policy,'scope':'Nanoseconds per column update, forward+inverse NTT pair, or dot product. Allocation and preparation excluded; dot includes one input-word mutation per call. Source-scalar controls retain compiler optimization.','results':[]}
def call(kind,n,p,reps,vector):
 cmd=[str(binary),kind,str(n),str(p),str(reps),str(vector)]
 return json.loads(subprocess.check_output(cmd,text=True,preexec_fn=lambda:os.sched_setaffinity(0,{0}),timeout=30))
for kind,n,p in cases:
 probe=call(kind,n,p,1000,0)
 repeats=max(1000,int(1000*policy['micro_min_seconds']*1e9/max(probe['ns'],1)))
 repeats=min(repeats,100_000_000)
 warm=[call(kind,n,p,repeats,v) for v in (0,1)]
 assert warm[0]['checksum']==warm[1]['checksum'],(kind,n,p,warm)
 rows={0:[],1:[]}
 for trial in range(policy['micro_trials']):
  for v in ([0,1] if trial%2==0 else [1,0]):
   r=call(kind,n,p,repeats,v);assert r['checksum']==warm[v]['checksum']
   rows[v].append(r['ns']/repeats)
 med={str(v):statistics.median(rows[v]) for v in rows}
 item={'kind':kind,'n':n,'p':p,'repetitions':repeats,'ns_per_call':rows,'median_ns':med,'speedup':med['0']/med['1'],'checksum':warm[0]['checksum']}
 report['results'].append(item)
 (folder/'micro.json').write_text(json.dumps(report,indent=2)+'\n')
 print(kind,n,p,'scalar',round(med['0'],2),'vector',round(med['1'],2),'ratio',round(item['speedup'],3),flush=True)

